    new import_obsidian.Setting(c)
      .setName(__ertr("\u0414\u0443\u0431\u043B\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u043A\u0430\u0440\u0442\u0438\u043D\u043A\u043E\u0439, \u0435\u0441\u043B\u0438 \u0435\u0441\u0442\u044C \u0442\u0435\u043A\u0441\u0442"))
      .setDesc(__ertr("\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0412\u042B\u041A\u041B: \u0435\u0441\u043B\u0438 \u0438\u0437 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0438\u0437\u0432\u043B\u0435\u043A\u0430\u0435\u0442\u0441\u044F \u0442\u0435\u043A\u0441\u0442 \u2014 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0438\u0441\u0442\u044B\u0439 \u0442\u0435\u043A\u0441\u0442, \u0431\u0435\u0437 \u0441\u043A\u0440\u0438\u043D\u0448\u043E\u0442\u0430. \u041A\u0430\u0440\u0442\u0438\u043D\u043A\u0430 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043B\u0438\u0448\u044C \u043A\u043E\u0433\u0434\u0430 \u0442\u0435\u043A\u0441\u0442 \u0438\u0437\u0432\u043B\u0435\u0447\u044C \u043D\u0435\u043B\u044C\u0437\u044F (\u0441\u043A\u0430\u043D\u044B, \u0441\u0445\u0435\u043C\u044B, \u043E\u0431\u043B\u043E\u0436\u043A\u0438). \u0412\u043A\u043B\u044E\u0447\u0438\u0442\u0435, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u0412\u0418\u0414\u0415\u0422\u042C \u043E\u0440\u0438\u0433\u0438\u043D\u0430\u043B\u044C\u043D\u044B\u0439 \u0440\u0438\u0441\u0443\u043D\u043E\u043A \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043D\u0430\u0434 \u0442\u0435\u043A\u0441\u0442\u043E\u043C (\u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0434\u043B\u044F \u043A\u043D\u0438\u0433-\u0441\u043A\u0435\u0442\u0447\u043D\u043E\u0443\u0442\u043E\u0432). \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443 \u0437\u0430\u043D\u043E\u0432\u043E, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C."))
