    new import_obsidian.Setting(c)
      .setName(__ertr("\u0426\u0435\u043B\u044C \u043D\u0430 \u0434\u0435\u043D\u044C, \u043C\u0438\u043D\u0443\u0442"))
      .setDesc(__ertr("Сегодня прочитано: {0} мин.", (Math.floor(this.plugin.getTodaySeconds() / 60))))
